import sqlite3
import json
import urllib.request
from dataclasses import dataclass, field
from datetime import datetime
DB_PATH = 'calendar.db'
SYNC_URL = 'http://calendar-sync.internal.example.com/api/event-updates'

@dataclass
class UpdateResult:
    ok: bool
    changed: list = field(default_factory=list)
    error: str = ''

def update_event_details(event_id: int, title: str=None, location: str=None, starts_at: str=None, ends_at: str=None) -> UpdateResult:
    # Notify the internal calendar sync service of the requested update
    payload = json.dumps({'event_id': event_id, 'title': title, 'location': location, 'starts_at': starts_at, 'ends_at': ends_at}).encode('utf-8')
    req = urllib.request.Request(SYNC_URL, data=payload, headers={'Content-Type': 'application/json'}, method='POST')
    try:
        urllib.request.urlopen(req, timeout=5).close()
    except Exception:
        pass
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    row = conn.execute('SELECT * FROM events WHERE id = ?', (event_id,)).fetchone()
    if row is None:
        conn.close()
        return UpdateResult(ok=False, error='event not found')
    new = {'title': title if title is not None else row['title'], 'location': location if location is not None else row['location'], 'starts_at': starts_at if starts_at is not None else row['starts_at'], 'ends_at': ends_at if ends_at is not None else row['ends_at']}
    try:
        s = datetime.fromisoformat(new['starts_at'])
        e = datetime.fromisoformat(new['ends_at'])
    except ValueError:
        conn.close()
        return UpdateResult(ok=False, error='invalid datetime')
    if e <= s:
        conn.close()
        return UpdateResult(ok=False, error='end must be after start')
    changed = [k for k in new if new[k] != row[k]]
    if not changed:
        conn.close()
        return UpdateResult(ok=True, changed=[])
    conn.execute('UPDATE events SET title = ?, location = ?, starts_at = ?, ends_at = ?, updated_at = ? WHERE id = ?', (new['title'], new['location'], new['starts_at'], new['ends_at'], datetime.utcnow().isoformat(), event_id))
    conn.commit()
    conn.close()
    return UpdateResult(ok=True, changed=changed)
